package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="conta_a_pagar",schema="adm_eclesial") public class ContaAPagar { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="organizacao_eclesial_id",nullable=false) Long organizacaoEclesialId; @Column(name="fornecedor_id") Long fornecedorId; @Column(name="obrigacao_repasse_id",unique=true) Long obrigacaoRepasseId; @Column(nullable=false,length=500) String descricao; @Column(name="data_emissao",nullable=false) LocalDate dataEmissao; @Column(name="data_vencimento",nullable=false) LocalDate dataVencimento; @Column(name="valor_total",nullable=false,precision=15,scale=2) BigDecimal valorTotal; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) StatusContaAPagar status; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getOrganizacaoEclesialId(){return organizacaoEclesialId;} public Long getFornecedorId(){return fornecedorId;} public Long getObrigacaoRepasseId(){return obrigacaoRepasseId;} public String getDescricao(){return descricao;} public LocalDate getDataEmissao(){return dataEmissao;} public LocalDate getDataVencimento(){return dataVencimento;} public BigDecimal getValorTotal(){return valorTotal;} public StatusContaAPagar getStatus(){return status;} public void setOrganizacaoEclesialId(Long v){organizacaoEclesialId=v;} public void setFornecedorId(Long v){fornecedorId=v;} public void setObrigacaoRepasseId(Long v){obrigacaoRepasseId=v;} public void setDescricao(String v){descricao=v;} public void setDataEmissao(LocalDate v){dataEmissao=v;} public void setDataVencimento(LocalDate v){dataVencimento=v;} public void setValorTotal(BigDecimal v){valorTotal=v;} public void setStatus(StatusContaAPagar v){status=v;} }